namespace ArbScanner.Learning;

/// <summary>One term: what it means, how it should change what you do, and a worked example.</summary>
public record GlossaryEntry(string Id, string Term, string Meaning, string HowItAffectsYou, string Example);

/// <summary>Every term the app uses. ⓘ buttons reference entries by <see cref="GlossaryEntry.Id"/>.</summary>
