    static readonly Dictionary<string, GlossaryEntry> ById = Entries.ToDictionary(e => e.Id);

    public static GlossaryEntry? Find(string id) => ById.GetValueOrDefault(id);

    public static IEnumerable<GlossaryEntry> Search(string? query) =>
        string.IsNullOrWhiteSpace(query)
            ? Entries
            : Entries.Where(e => e.Term.Contains(query, StringComparison.OrdinalIgnoreCase)
                                 || e.Meaning.Contains(query, StringComparison.OrdinalIgnoreCase));
}
